// spec: .qa/e2e/specs/content-filter.md 1.1 · тикет #2ee07c55 (AC 1, 5, 7)
// Две роли (пишется вручную): user4 публикует пост «QA-AUTO … איזה חרא של יום» (тем же запросом, что приложение) →
// admin видит его в «לבדיקה» с пометкой «סינון אוטומטי» и причиной «מילה אסורה «חרא»»; пост остаётся видимым (только пометка).
// @data: в finally user4 удаляет пост — вместе с ним уходит и автоматическая жалоба (проверено 12.11).
import { test, expect } from '@playwright/test';
import type { Page } from '@playwright/test';
import { ADMIN_URL, adminAs, appApi, cId, closeAdmin, closeApp, contentAside, contentDetail, contentQueue, createPost, deletePost, iphoneAs, postVisibleToAuthor, tag } from '../moderation-menu/mod-helpers';
import type { Api } from '../_shared/api';

test.describe('סינון תוכן אוטומטי בסיסי', () => {
  test('Пост с бранным словом «חרא» — в «לבדיקה» с «סינון אוטומטי: מילה אסורה «חרא»», пост виден автору; после удаления автором пропадает из очереди @desktop @data (#2ee07c55)', async ({ browser }) => {
    test.setTimeout(150_000);
    const user = await iphoneAs(browser, 'user4');
    let admin: Page | undefined;
    let api: Api | undefined;
    let id = '';
    const text = `QA-AUTO 2ee07c55 ${tag(5)} איזה חרא של יום`;
    try {
      api = await appApi(user);
      id = await createPost(api, text);

      admin = await adminAs(browser);
      await admin.goto(`${ADMIN_URL}/content?tab=review`);
      const row = contentQueue(admin).getByRole('link', { name: new RegExp(cId(id)) });
      await expect(row).toContainText(text);
      await row.click();
      await expect(admin).toHaveURL(new RegExp(`id=${id}`));

      // Причина в «למה בבדיקה» (AC 1, 5)
      const why = contentDetail(admin).getByRole('listitem').filter({ hasText: 'סינון אוטומטי:' });
      await expect(why).toContainText('סינון אוטומטי');
      await expect(why).toContainText(/סיבה:\s*סיבה אחרת/);
      await expect(why).toContainText('סינון אוטומטי: מילה אסורה «חרא»');
      await expect(contentAside(admin)).toContainText(/מקור\s*סינון אוטומטי/);

      // Только пометка: пост по-прежнему виден (AC 5 / комментарий программиста)
      expect(await postVisibleToAuthor(api, id), 'пост виден после пометки').toBe(true);

      // Очистка: автор удаляет пост → элемент уходит из «לבדיקה»
      await deletePost(api, id);
      expect(await postVisibleToAuthor(api, id)).toBe(false);
      id = '';
      await admin.goto(`${ADMIN_URL}/content?tab=review`);
      await expect(contentQueue(admin).getByRole('tab', { name: /^לבדיקה/ })).toHaveAttribute('aria-selected', 'true');
      await expect(contentQueue(admin).getByText(text)).toHaveCount(0);
    } finally {
      if (api && id) await deletePost(api, id);
      await closeAdmin(admin);
      await closeApp(user, 'user4');
    }
  });
});
